'use strict';
function random(seed){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}}
const palettes={jade:{sky:'#e5eadd',water:'#a9c6b5',far:'#91ae9e',mid:'#547d6c',near:'#264e42',paper:'#f5f1e6',sun:'#ded3a0'},ink:{sky:'#e9e8df',water:'#ccd0c6',far:'#acb4aa',mid:'#717e73',near:'#35453d',paper:'#f5f2e8',sun:'#d2c5b1'},dusk:{sky:'#e9d7c6',water:'#b9b4a6',far:'#b8a79b',mid:'#8c8f83',near:'#4f665d',paper:'#f6eee2',sun:'#dc9d6c'}};
function configureCanvas(canvas){const rect=canvas.getBoundingClientRect();const dpr=Math.min(window.devicePixelRatio||1,2);const w=Math.max(rect.width,1),h=Math.max(rect.height,1);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return{ctx,w,h}}
function mountainPath(ctx,x,base,width,height,seed){const rng=random(seed);const points=[];const peak=x+width*(.4+rng()*.2);ctx.beginPath();ctx.moveTo(x,base);ctx.bezierCurveTo(x+width*.1,base-height*.08,x+width*.16,base-height*.28,x+width*.23,base-height*.48);ctx.bezierCurveTo(x+width*.27,base-height*.62,peak-width*.16,base-height*(.94+rng()*.05),peak-width*.06,base-height*.98);ctx.bezierCurveTo(peak+width*.04,base-height*1.03,peak+width*.15,base-height*.98,peak+width*.19,base-height*.82);ctx.bezierCurveTo(x+width*.8,base-height*.46,x+width*.82,base-height*.13,x+width,base);ctx.closePath();return points}
function renderLandscape(ctx,w,h,opts={}){const p=palettes[opts.palette||'jade'],rng=random(opts.composition==='peaks'?927:opts.composition==='blank'?31:517),mist=opts.mist??.45,boat=opts.boat??true;ctx.save();ctx.clearRect(0,0,w,h);const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,p.sky);sky.addColorStop(.63,p.sky);sky.addColorStop(1,p.water);ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);ctx.fillStyle=p.sun;ctx.globalAlpha=.65;ctx.beginPath();ctx.arc(w*.72,h*.2,h*.06,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 const layers=[{base:.52,min:.15,max:.28,col:p.far,count:12,width:.19},{base:.61,min:.22,max:.39,col:p.mid,count:9,width:.23},{base:.72,min:.3,max:.51,col:p.near,count:6,width:.26}];
 if(opts.composition==='peaks')layers.forEach(l=>{l.min*=1.2;l.max*=1.2;l.count+=2;l.width*=.83});
 layers.forEach((l,li)=>{for(let i=0;i<l.count;i++){const x=(i/(l.count-1))*w*1.3-w*.14+(rng()-.5)*w*.035;const width=w*l.width*(.7+rng()*.55);const ht=h*(l.min+rng()*(l.max-l.min));const base=h*l.base;if(opts.composition==='blank'&&x<w*.43)continue;ctx.fillStyle=l.col;ctx.globalAlpha=li===0?.56:li===1?.72:.91;mountainPath(ctx,x,base,width,ht,100+i+li*30);ctx.fill();ctx.save();ctx.beginPath();mountainPath(ctx,x,base,width,ht,100+i+li*30);ctx.clip();ctx.strokeStyle='#f1f2df';ctx.globalAlpha=.07;ctx.lineWidth=.7;for(let j=0;j<16;j++){const xx=x+width*rng();ctx.beginPath();ctx.moveTo(xx,base);ctx.bezierCurveTo(xx-width*.05,base-ht*.4,xx+width*.07,base-ht*.6,xx+width*.03,base-ht);ctx.stroke()}ctx.restore()}
 ctx.globalAlpha=1;const fog=ctx.createLinearGradient(0,h*(l.base-.17),0,h*(l.base+.05));fog.addColorStop(0,p.sky+'00');fog.addColorStop(.8,p.sky+(Math.round((.12+mist*.58)*255).toString(16).padStart(2,'0')));fog.addColorStop(1,p.sky+'00');ctx.fillStyle=fog;ctx.fillRect(0,h*(l.base-.17),w,h*.22)});
 ctx.globalAlpha=1;const river=ctx.createLinearGradient(0,h*.65,0,h);river.addColorStop(0,p.water+'22');river.addColorStop(1,p.water);ctx.fillStyle=river;ctx.beginPath();ctx.moveTo(w*.57,h*.59);ctx.bezierCurveTo(w*.31,h*.75,w*.73,h*.75,w*.28,h);ctx.lineTo(w*1.05,h);ctx.bezierCurveTo(w*.72,h*.83,w*.85,h*.71,w*.64,h*.59);ctx.closePath();ctx.fill();
 ctx.strokeStyle=p.sky;ctx.globalAlpha=.35;ctx.lineWidth=.7;for(let i=0;i<60;i++){const y=h*(.7+rng()*.3),x=rng()*w;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+15+rng()*w*.06,y);ctx.stroke()}ctx.globalAlpha=1;
 if(boat){const x=w*(opts.composition==='blank'?.38:.61),y=h*.85,s=w/950;ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle=p.near;ctx.beginPath();ctx.moveTo(-26,0);ctx.quadraticCurveTo(0,11,28,-2);ctx.lineTo(20,7);ctx.lineTo(-18,8);ctx.closePath();ctx.fill();ctx.strokeStyle=p.near;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(4,0);ctx.lineTo(3,-19);ctx.moveTo(3,-15);ctx.lineTo(13,-8);ctx.moveTo(12,-23);ctx.lineTo(25,6);ctx.stroke();ctx.beginPath();ctx.arc(3,-23,3.5,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.2;ctx.scale(1,-.5);ctx.beginPath();ctx.ellipse(0,-20,30,5,0,0,Math.PI*2);ctx.fill();ctx.restore()}
 ctx.restore()}
